namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
            AverageRating = 4.5, RatingCount = 24
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.",
            AverageRating = 4.8, RatingCount = 31
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Cumin, Tomato sauce, Heavy cream, Ginger, Garlic",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté ginger and garlic in butter.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.",
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs",
            Steps = "1. Soak rice noodles in warm water.\n2. Mix tamarind paste, fish sauce, and sugar for sauce.\n3. Stir-fry tofu until golden.\n4. Scramble eggs in the same pan.\n5. Add noodles and sauce, toss well.\n6. Garnish with peanuts, bean sprouts, and lime.",
            AverageRating = 4.3, RatingCount = 12
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Cumin, Chili powder",
            Steps = "1. Brown ground beef with cumin and chili powder.\n2. Warm taco shells in oven.\n3. Shred lettuce and dice tomatoes.\n4. Grate cheddar cheese.\n5. Assemble tacos with beef and toppings.\n6. Serve with sour cream and salsa.",
            AverageRating = 4.1, RatingCount = 15
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract",
            Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold chocolate mixture into eggs.\n4. Add flour and vanilla, mix gently.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12-14 minutes.\n7. Invert onto plate and serve immediately.",
            AverageRating = 4.9, RatingCount = 42
        },
        new Recipe
        {
            Id = 7, Title = "Miso Ramen", Category = "Asian",
            Ingredients = "Ramen noodles, Miso paste, Pork belly, Soft-boiled egg, Green onions, Nori, Chicken broth, Soy sauce",
            Steps = "1. Simmer chicken broth with miso paste.\n2. Slice and sear pork belly.\n3. Cook ramen noodles according to package.\n4. Soft-boil eggs (6 minutes).\n5. Assemble bowls with noodles and broth.\n6. Top with pork, egg, nori, and green onions.",
            AverageRating = 4.6, RatingCount = 22
        },
        new Recipe
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt",
            Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño.\n4. Chop cilantro.\n5. Mix everything with lime juice and salt.\n6. Serve immediately with tortilla chips.",
            AverageRating = 4.4, RatingCount = 28
        }
    };

    private static readonly List<RecipeCategory> _categories = new()
    {
        new RecipeCategory { Name = "Italian", Description = "Classic pasta, pizza, and Mediterranean flavors", Icon = "🍝" },
        new RecipeCategory { Name = "Indian", Description = "Rich curries, aromatic spices, and tandoori dishes", Icon = "🍛" },
        new RecipeCategory { Name = "Asian", Description = "Stir-fries, noodles, and umami-packed bowls", Icon = "🍜" },
        new RecipeCategory { Name = "Mexican", Description = "Bold flavors with chilies, lime, and fresh herbs", Icon = "🌮" },
        new RecipeCategory { Name = "Desserts", Description = "Sweet treats and indulgent baked goods", Icon = "🍰" }
    };

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalRating + rating) / recipe.RatingCount, 1);
        }
    }
}

