@page "/"

<PageTitle>Recipe Community - Home</PageTitle>

<h1>Welcome to Recipe Community 🍳</h1>
<p class="lead">Discover, share, and rate delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in categories)
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h2>@category.Icon</h2>
                    <h5 class="card-title">@category.Name</h5>
                    <p class="card-text">@category.Description</p>
                    <a href="categories/@category.Name.ToLower()" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeCommunity.Models.RecipeCategory> categories = new();

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }
}

toolArgs.file_text:
@page "/categories"
@page "/categories/{CategoryName}"

<PageTitle>@(CategoryName ?? "All Categories") - Recipe Community</PageTitle>

@if (string.IsNullOrEmpty(CategoryName))
{
    <h1>Recipe Categories</h1>
    <div class="row">
        @foreach (var category in categories)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100">
                    <div class="card-body text-center">
                        <h2>@category.Icon</h2>
                        <h5 class="card-title">@category.Name</h5>
                        <p class="card-text">@category.Description</p>
                        <a href="categories/@category.Name.ToLower()" class="btn btn-outline-primary">View Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-sm btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string? CategoryName { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeCommunity.Models.RecipeCategory> categories = new();
    private List<RecipeCommunity.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        categories = RecipeService.GetCategories();
        if (!string.IsNullOrEmpty(CategoryName))
        {
            recipes = RecipeService.GetRecipesByCategory(CategoryName);
        }
    }
}

